exec(open('tools/common.py').read())
# Intermediate unit 70 – Academic writing. Bám sách: trang 144–145 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# Đã có thẻ cùng nghĩa → chỉ nhắc: start off (u62), set out (u44), touch on (u44), sum up (u44), come back to (u31), turn to (u35),
# come to = đi đến kết luận (u6), draw on (u35), point out (u35), go on = tiếp tục (u8).
# move on (Mini 64: continue to the next point) xuất hiện trên trang này → thẻ.
theory = (
 H("A", "Structuring your writing", "Bố cục bài viết")
 + P("<b>Opening:</b> you can <b>start off by</b> outlining research (begin – card in Unit 62), and say that the first section <b>sets out</b> the main points (explains them in order – card in Unit 44).",
     "<b>Mở bài:</b> có thể <b>start off by</b> điểm qua nghiên cứu (bắt đầu – đã có thẻ ở bài 62), và nói phần đầu <b>sets out</b> các ý chính (trình bày có trật tự – đã có thẻ ở bài 44).")
 + P("<b>Changing topic or referring:</b> <b>moving on</b> (going to the next point); <b>turning to</b> another effect (changing topic – card in Unit 35); <b>touch on</b> a study (mention briefly – card in Unit 44); <b>come back to</b> / <b>go back to</b> an earlier point (refer back – card in Unit 31); <b>follow up on</b> a point (add more information about it); a point that research <b>picks up on</b> (connects to and develops); arguments <b>relating to</b> a scheme (connected to it); a theory <b>based on</b> two projects (using them as a starting point).",
     "<b>Chuyển ý, dẫn chiếu:</b> <b>moving on</b> (sang ý tiếp); <b>turning to</b> tác động khác (chuyển chủ đề – đã có thẻ ở bài 35); <b>touch on</b> một nghiên cứu (nhắc qua – đã có thẻ ở bài 44); <b>come back to</b> / <b>go back to</b> ý trước (quay lại – đã có thẻ ở bài 31); <b>follow up on</b> một ý (bổ sung thông tin); ý mà nghiên cứu <b>picks up on</b> (nối tiếp, khai thác thêm); lập luận <b>relating to</b> một chương trình (liên quan đến); lý thuyết <b>based on</b> hai dự án (lấy làm nền tảng).")
 + P("<b>Concluding:</b> <b>sum up</b> the key finding (summarise – card in Unit 44); <b>draw together</b> or <b>bring together</b> themes and results (collect them); <b>arrive at</b> a conclusion (reach it – also <i>come to</i>, card in Unit 6).",
     "<b>Kết bài:</b> <b>sum up</b> phát hiện chính (tóm tắt – đã có thẻ ở bài 44); <b>draw together</b> hay <b>bring together</b> các chủ đề, kết quả (tập hợp lại); <b>arrive at</b> kết luận (đi đến – cũng nói <i>come to</i>, đã có thẻ ở bài 6).")
 + NOTE("<b>Tip:</b> <i>start off by</i> is always followed by an <i>-ing</i> form.", "<b>Mẹo:</b> sau <i>start off by</i> luôn là dạng <i>-ing</i>.")
 + H("B", "More phrasal verbs for writing", "Thêm phrasal verb cho bài viết")
 + P("A researcher <b>goes on</b> to suggest something (continues – card in Unit 8); a writer has <b>drawn on</b> earlier findings (used them – card in Unit 35); it is important to <b>point out</b> a limitation (emphasise it – card in Unit 35); a section <b>focuses on</b> the economy (gives it a lot of attention); one factor <b>accounts for</b> negative responses (explains them).",
     "Nhà nghiên cứu <b>goes on</b> đưa ra gợi ý (tiếp tục – đã có thẻ ở bài 8); người viết đã <b>drawn on</b> các phát hiện trước (dựa vào – đã có thẻ ở bài 35); cần <b>point out</b> một hạn chế (nhấn mạnh – đã có thẻ ở bài 35); một phần <b>focuses on</b> kinh tế (tập trung vào); một yếu tố <b>accounts for</b> các phản hồi tiêu cực (giải thích).")
 + NOTE("<b>Tip:</b> in academic writing <i>go on to</i> is often followed by <i>say/argue/describe</i>.", "<b>Mẹo:</b> trong văn học thuật, sau <i>go on to</i> thường là <i>say/argue/describe</i>.")
)
